#!/usr/bin/env node
/* =====================================================================
   tools/web-bundle.js — the page for a server (the .NET and Java ports)

     node tools/web-bundle.js <dir>

   Writes the same page this project shows, minus the in-browser engine,
   into <dir>, in the layout the ports serve from their web/ folder:

     index.html            this project's index.html with the script list
                           src/config.js, src/script.js, src/client.js,
                           data/catalog.js, data/marcus.js, src/app.js
                           (no vendor/, warehouse/, context/, engine,
                           analyses, evals or service files)
     assets/               styles, fonts, logos (copied)
     src/config.js, src/script.js, src/app.js   (copied)
     src/client.js         MCX.engine, MCX.db, MCX.context and MCX.service
                           over the HTTP API (docs/API.md)
     data/marcus.js        the recorded replays (copied)

   data/catalog.js is not written: the server generates it from its
   question bank (data/catalog.json in the ports). Try the bundle with
     node tools/server.js --web <dir> --mode overlay --var <scratch dir>
   ===================================================================== */
'use strict';

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const SCRIPTS = ['src/config.js', 'src/script.js', 'src/client.js', 'data/catalog.js', 'data/marcus.js', 'src/app.js'];
const COPY = ['src/config.js', 'src/script.js', 'src/client.js', 'src/app.js', 'data/marcus.js'];

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true });
  fs.readdirSync(from, { withFileTypes: true }).forEach((e) => {
    if (e.name.startsWith('.')) return;
    const a = path.join(from, e.name), b = path.join(to, e.name);
    if (e.isDirectory()) copyDir(a, b); else fs.copyFileSync(a, b);
  });
}

/** This project's index.html, rewritten for a page that reaches the engine over HTTP. */
function webIndex() {
  let html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');
  const boot = /(<strong[^>]*>The demo files did not load\.<\/strong>)[\s\S]*?(\n\s*JavaScript also needs)/;
  if (!boot.test(html)) throw new Error('index.html: the boot note has changed; update tools/web-bundle.js');
  html = html.replace(boot, '$1\n    This page is served by the McContext server. Start it (see README.md) and open the address it prints.$2');
  const first = html.indexOf('  <!-- Order matters');
  const last = html.indexOf('  <script>', first);
  if (first === -1 || last === -1) throw new Error('index.html: the script list has changed; update tools/web-bundle.js');
  const list = '  <!-- The page, its settings and the recorded replays. The warehouse, the context layer, the engine and\n' +
    '       MCX.service run on the server; src/client.js connects to them over the HTTP API (docs/API.md).\n' +
    '       data/catalog.js is generated by the server from its question bank. -->\n' +
    SCRIPTS.map((s) => '  <script src="' + s + '"></script>\n').join('');
  return html.slice(0, first) + list + html.slice(last);
}

function bundle(dir) {
  const out = path.resolve(dir);
  fs.mkdirSync(out, { recursive: true });
  copyDir(path.join(root, 'assets'), path.join(out, 'assets'));
  COPY.forEach((rel) => {
    const to = path.join(out, ...rel.split('/'));
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(path.join(root, ...rel.split('/')), to);
  });
  fs.writeFileSync(path.join(out, 'index.html'), webIndex());
  return out;
}

if (require.main === module) {
  const dir = process.argv[2];
  if (!dir) { console.error('Usage: node tools/web-bundle.js <dir>'); process.exit(1); }
  const out = bundle(dir);
  console.log('Wrote the server page to ' + out + ' (index.html, assets/, ' + COPY.join(', ') + ')');
}

module.exports = { bundle, webIndex, SCRIPTS };
